static int f(int a) {
    Point p = new Point(a, a);
    if (a < 0) LOG.add(p);       // a rare leak still makes p escape
    return p.x() + p.y();
}

// fix: leak only a copy in the rare branch
static int g(int a) {
    Point p = new Point(a, a);
    if (a < 0) LOG.add(new Point(a, a));
    return p.x() + p.y();
}

// OUTPUT:
// g() can be scalar replaced; f() allocates on the heap

